use std::path::Path;use artifactum_core::{AcquireContext,Acquisition,AcquisitionPlan,ArtifactProvider,ArtifactRequirement,ProviderCapabilities,ProviderDescriptor,ResolveContext,Resolution,ResolvedFile};use artifactum_provider_command::{file_name,find_and_copy,required_fragment,run_checked_in,single_file_resolution,source_with,string_field,tempdir};use async_trait::async_trait;
#[derive(Clone,Debug,Default)]pub struct CometProvider;
#[async_trait]impl ArtifactProvider for CometProvider{fn descriptor(&self)->ProviderDescriptor{ProviderDescriptor{name:"comet".into(),version:env!("CARGO_PKG_VERSION").into(),schemes:vec!["comet".into()],capabilities:ProviderCapabilities{resolve:true,acquire:true,auth:true,..Default::default()},metadata:Default::default()}}async fn resolve(&self,r:&ArtifactRequirement,_:&ResolveContext)->artifactum_core::Result<Resolution>{let(root,path)=required_fragment("comet",r.reference.locator(),"path")?;single_file_resolution("comet",format!("comet:{root}#{path}"),r,path,source_with([("resource",root.into()),("path",path.into())]))}async fn prepare_acquisition(&self,f:&ResolvedFile,_:&AcquireContext)->artifactum_core::Result<AcquisitionPlan>{Ok(AcquisitionPlan::ProviderManaged{state:f.source.clone()})}async fn acquire_managed(&self,f:&ResolvedFile,_:&AcquisitionPlan,d:&Path,_:&AcquireContext)->artifactum_core::Result<Acquisition>{let resource=string_field(&f.source,"resource","comet")?;let path=string_field(&f.source,"path","comet")?;let tmp=tempdir("comet")?;let filename=file_name(path);run_checked_in("comet","cometx",["download",resource,"--filename",&filename,"--flat"],tmp.path()).await?;let n=find_and_copy(tmp.path(),path,d,"comet").await?;Ok(Acquisition{bytes_written:Some(n),metadata:Default::default()})}}
pub fn provider()->CometProvider{CometProvider}
